        // shadow: this view is of the north side, so the light is north-west. Mid altitude, because
        // a low sun here puts the whole massif in its own shadow.
        map.light(Spec.of("light")
            .set("terrainLightingEnabled", true)
            .set("sunAzimuth", 315)
            .set("sunAltitude", 42)
