    for (NSArray *summit in summits()) {
        if (fabs([position getX] - [summit[1] doubleValue]) < 1e-4 &&
            fabs([position getY] - [summit[2] doubleValue]) < 1e-4) {
            name = summit[0];
            metres = [summit[3] intValue];
        }
    }
